SELECT id, series_code, series_name, COALESCE(source,'') AS source, COALESCE(license,'') AS license, COALESCE(code_prefix,'') AS code_prefix, COALESCE(file_name,'') AS file_name, COALESCE(display_title,'') AS display_title, status, COALESCE(fail_reason,'') AS fail_reason, COALESCE(report,'') AS report, created_at, COALESCE(NULLIF(lesson_level,''),'全部') AS lesson_level, COALESCE(rewrite,1) AS rewrite, COALESCE(overwrite,0) AS overwrite, COALESCE(subject_id,1) AS subject_id FROM textbook_import_task WHERE id = CAST(:id AS INTEGER)
